INSERT INTO business_process_definition
(process_code,name,purpose,owner_name,trigger_description,outcome_description,version_number,status,technical_reference,process_type,parent_process_code,execution_scope,diagram_json,created_at,published_at)
SELECT 'opala-commercial-preparation-v1','Preparar operação comercial Opala','Preparar a venda da experiência Opala com agentes e provas da mesma versão.','Backend e agentes especializados','Ciclo Opala em preparação comercial, antes de liberar tráfego.','Preparação comprovada; publicação, gasto, venda e entrega real mantêm gates próprios.',1,'PUBLISHED','docs/canonical/product-types-canon.v1.md','SUBPROCESS','pde-sales-delivery-learning','PRODUCT','{"schemaVersion":"OPALA_COMMERCIAL_PREPARATION_V1","productTypeCode":"PDE","nodes":[{"id":"start","type":"START","label":"Produto Opala e ciclo identificados"},{"id":"entry","type":"TASK","label":"Preparar entrada do próprio PDE","owner":"Dédalo","description":"Preparar slot em rascunho da versão aprovada, sem landing separada ou publicação.","responsibleAgentKeys":["landing-generator"]},{"id":"creative","type":"TASK","label":"Vincular e preparar criativo aprovado","owner":"Dédalo · integração da comunicação de Íris e Apolo","description":"Reutilizar o vídeo AD aprovado e materializar anúncio em rascunho fiel à oferta; manter revisão e aprovação final.","responsibleAgentKeys":["landing-generator"]},{"id":"checkout","type":"TASK","label":"Configurar checkout e acesso","owner":"Dédalo","description":"Vincular checkout canônico da mesma oferta e versão; homologação posterior comprova acesso após compra simulada.","responsibleAgentKeys":["landing-generator"]},{"id":"targeting","type":"TASK","label":"Preparar público aprovado por Atena","owner":"Dédalo · integração da estratégia de Atena","description":"Salvar somente elementos oficiais aprovados, preservando a segmentação definida na estratégia.","responsibleAgentKeys":["landing-generator"]},{"id":"economics","type":"TASK","label":"Validar custos, limites e margem","owner":"Plutus","description":"Revalidar preço, custo de IA, mídia, entrega, margem e janela da mesma versão e orçamento; não autorizar gasto.","responsibleAgentKeys":["financial-agent"]},{"id":"humanExperienceReview","type":"TASK","label":"Homologar experiência comercial","owner":"Psique","description":"Avaliar anúncio, entrada do PDE, oferta, checkout e entrega de teste na versão preparada; preservar segregação e evidências visuais.","responsibleAgentKeys":["customer-agent"]},{"id":"commercialIntegrityReview","type":"TASK","label":"Revisar integridade da jornada","owner":"Têmis","description":"Revisar provas, oferta, preço, privacidade, checkout e entrega simulada; não conceder autorização humana.","responsibleAgentKeys":["meta-ad-approver"]},{"id":"ready","type":"TASK","label":"Concluir preparação comercial","owner":"Backend","description":"Consolidar entregas e gates atuais, sem ativar campanha nem comprovar venda ou entrega real."},{"id":"end","type":"END","label":"Preparação comprovada; retornar ao processo de vendas"}],"flows":[{"to":"entry","from":"start"},{"to":"creative","from":"entry"},{"to":"checkout","from":"creative"},{"to":"targeting","from":"checkout"},{"to":"economics","from":"targeting"},{"to":"humanExperienceReview","from":"economics"},{"to":"commercialIntegrityReview","from":"humanExperienceReview"},{"to":"ready","from":"commercialIntegrityReview"},{"to":"end","from":"ready"}]}',UTC_TIMESTAMP(),UTC_TIMESTAMP()
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM business_process_definition WHERE process_code='opala-commercial-preparation-v1' AND version_number=1);

INSERT INTO business_process_definition
(process_code,name,purpose,owner_name,trigger_description,outcome_description,version_number,status,technical_reference,process_type,parent_process_code,execution_scope,diagram_json,created_at,published_at)
SELECT process_code,name,purpose,owner_name,trigger_description,outcome_description,7,'PUBLISHED',technical_reference,process_type,parent_process_code,execution_scope,'{"nodes":[{"id":"start","type":"START","label":"Experimento identificado","owner":"Backend","description":"Entrada por operação autorizada ou referência histórica comprovada, sempre vinculada ao produto e experimento."},{"id":"entry","type":"GATEWAY","label":"Operação atual ou referência histórica?","owner":"Backend","description":"Adoção histórica exige evento ADOPT_BASELINE e evidência de publicação, sem aprovação retroativa."},{"id":"parallel","type":"GATEWAY","label":"Operação e entrega durante as vendas","owner":"Backend","description":"Ramos paralelos explícitos; a entrega de uma compra não aguarda o encerramento do experimento."},{"id":"sales","type":"GATEWAY","label":"Existem vendas no recorte?","owner":"Backend","description":"Somente fonte válida pode comprovar zero vendas. Nenhuma venda implica entrega não aplicável nesta passagem."},{"id":"commercialPreparation","type":"TASK","label":"Preparar operação comercial Opala","owner":"Backend · agentes responsáveis","description":"Executar preparação específica do tipo Opala no ciclo e experimento atuais. Outros tipos e referências históricas não exigem preparação retroativa.","subprocessCode":"opala-commercial-preparation-v1"},{"id":"optimization","type":"TASK","label":"Operar e otimizar o experimento","owner":"Backend","description":"Delega aquisição, mensuração e teste de variável ao subprocesso canônico.","subprocessCode":"operacao-otimizacao-experimento"},{"id":"delivery","type":"TASK","label":"Entregar cada venda e acompanhar satisfação","owner":"Backend","description":"Delega conciliação, entrega, suporte, satisfação e reembolso ao subprocesso canônico.","subprocessCode":"venda-entrega-satisfacao-cliente"},{"id":"consolidate","type":"TASK","label":"Consolidar resultado comercial","owner":"Backend","description":"O backend concilia automaticamente fontes do experimento. Fonte inválida bloqueia; não é preenchimento manual nem ausência igual a zero."},{"id":"learningCycle","type":"TASK","label":"Conduzir o ciclo de aprendizado e vendas","owner":"Operador responsável pelo produto","description":"Abra ou retome o ciclo deste produto e experimento. Concilie resultados, registre a decisão e siga a atividade orientada. Mudança comercial exige experimento sucessor com o aprendizado anterior; correção técnica permanece na mesma iteração com revalidação.","subprocessCode":"value-chain-learning-sales-cycle"},{"id":"decision","type":"GATEWAY","label":"Qual decisão comercial?","owner":"Backend e operador humano","description":"A decisão persistida no ciclo determina o retorno pela causa. Continuar coleta respeita janela e orçamento. Ajustar estratégia, produto ou comunicação exige revalidação; escala exige nova autorização. Encerrar preserva resultados e limitações."},{"id":"join","type":"GATEWAY","label":"Resultados e situação das entregas disponíveis","owner":"Backend","description":"Consolidar situação comercial e entregas, preservando bloqueios e ausência comprovada de vendas."},{"id":"returnTarget","type":"GATEWAY","label":"Retorno ao processo da causa: 2, 3 ou 4","owner":"Backend","description":"A decisão identifica processo e atividade. Mudança comercial usa sucessor; correção técnica preserva o experimento. Executar gates no 5 antes de operar."},{"id":"returnAuthorization","type":"GATEWAY","label":"Processo 5: homologação e autorização","owner":"Backend e operador","description":"Renovar os gates afetados e autorização explícita antes da publicação ou escala; retorno registrado não autoriza gasto por si só."},{"id":"end","type":"END","label":"Ciclo decidido por vendas entregues","owner":"Backend","description":"A decisão e suas evidências ficam auditáveis."}],"flows":[{"id":"identify","from":"start","to":"entry","label":"Fixar produto e experimento"},{"id":"live-entry","from":"entry","to":"parallel","label":"Publicação atual autorizada"},{"id":"historical-entry","from":"entry","to":"consolidate","label":"ADOPT_BASELINE: publicação histórica comprovada; preservar limitações"},{"id":"operate","from":"parallel","to":"optimization","label":"Operação com limites vigentes"},{"id":"delivery-condition","from":"parallel","to":"sales","label":"Entregar cada compra durante a operação"},{"id":"has-sales","from":"sales","to":"delivery","label":"Vendas existentes: entrega obrigatória"},{"id":"no-sales","from":"sales","to":"join","label":"Zero vendas comprovado: entrega não aplicável nesta passagem"},{"id":"operation-snapshot","from":"optimization","to":"join","label":"Rodada de resultados disponível"},{"id":"delivery-snapshot","from":"delivery","to":"join","label":"Situação das entregas registrada"},{"id":"consolidation","from":"join","to":"consolidate","label":"Fontes e limites do mesmo experimento"},{"id":"measurement-ready","from":"consolidate","to":"learningCycle","label":"MEASURE: leitura válida; obrigações de entrega verificadas"},{"id":"measurement-blocked","from":"consolidate","to":"consolidate","label":"MEASUREMENT_BLOCKED: corrigir fonte e repetir conciliação","kind":"REWORK"},{"id":"delivery-blocked","from":"consolidate","to":"delivery","label":"Venda sem entrega comprovada: tratar e reconsolidar","kind":"REWORK"},{"id":"decision-recorded","from":"learningCycle","to":"decision","label":"Decisão, causa, evidência, responsável e destino registrados"},{"id":"continue-collection","from":"decision","to":"optimization","label":"CONTINUE: mesmo experimento, dentro do orçamento e janela","kind":"REWORK"},{"id":"fix-measurement","from":"decision","to":"consolidate","label":"FIX_MEASUREMENT: corrigir e reconciliar a fonte; sem reiniciar campanha","kind":"REWORK"},{"id":"directed-adjustment","from":"decision","to":"returnTarget","label":"ADJUST / REWORK: executar retorno registrado pela causa","kind":"REWORK"},{"id":"delegated-progress","from":"returnTarget","to":"learningCycle","label":"Etapas delegadas concluídas com evidência no ciclo","kind":"REWORK"},{"id":"request-scale","from":"decision","to":"returnAuthorization","label":"SCALE: contribuição e valor comprovados; solicitar autorização","kind":"REWORK"},{"id":"revalidate","from":"returnTarget","to":"returnAuthorization","label":"Melhoria pronta: revalidar a mesma versão"},{"id":"authorized-scale","from":"returnAuthorization","to":"optimization","label":"AUTHORIZE_SCALE: expansão explicitamente autorizada","kind":"REWORK"},{"id":"publication-measurement","from":"returnAuthorization","to":"consolidate","label":"Publicação comprovada após gates próprios"},{"id":"close-cycle","from":"decision","to":"end","label":"STOP / INCONCLUSIVE: preservar resultados e motivos"},{"id":"prepare-entry","from":"start","to":"commercialPreparation","label":"Opala em preparação do ciclo"},{"id":"prepare-return","from":"commercialPreparation","to":"entry","label":"Prontidão comprovada; decisões de publicação continuam próprias"}],"learningCycleReturns":[{"label":"Estratégia e economia","condition":"A evidência exige rever oferta, preço ou viabilidade. Defina a hipótese do sucessor.","processCode":"pde-commercial-plan-offer"},{"label":"Utilidade do produto","condition":"A cliente não consegue aplicar o resultado ou perceber valor. Corrija a entrega e renove os pareceres.","processCode":"pde-construction-approval"},{"label":"Comunicação e vídeos","condition":"O benefício ou a entrada não são compreendidos. Ajuste mensagem, demonstração e criativo.","processCode":"pde-communication-sales-journey"},{"label":"Homologação e autorização","condition":"Depois dos ajustes, valide a mesma versão e obtenha autorização explícita antes de publicar ou expandir.","processCode":"pde-commercial-homologation-activation"},{"label":"Coleta e medição","condition":"Continuar somente com dados válidos dentro dos limites; corrigir dados inválidos antes de decidir sobre desempenho.","processCode":"pde-sales-delivery-learning"}],"salesFlowVersion":1,"opalaPreparationVersion":1}',UTC_TIMESTAMP(),UTC_TIMESTAMP()
FROM business_process_definition source WHERE process_code='pde-sales-delivery-learning' AND version_number=6
AND NOT EXISTS (SELECT 1 FROM business_process_definition target WHERE target.process_code=source.process_code AND target.version_number=7);

