INSERT INTO business_process_chain_definition
(chain_code,name,purpose,outcome_description,primary_metric,version_number,status,created_at,published_at)
SELECT chain_code,name,purpose,outcome_description,primary_metric,15,'PUBLISHED',UTC_TIMESTAMP(),UTC_TIMESTAMP()
FROM business_process_chain_definition source WHERE chain_code='pde-value-creation-delivery' AND version_number=14
AND NOT EXISTS (SELECT 1 FROM business_process_chain_definition target WHERE target.chain_code=source.chain_code AND target.version_number=15);

INSERT INTO business_process_chain_item
(chain_definition_id,process_definition_id,sequence_number,value_contribution,created_at)
SELECT target.id,CASE WHEN previous.process_code='pde-sales-delivery-learning' THEN updated.id ELSE item.process_definition_id END,item.sequence_number,item.value_contribution,UTC_TIMESTAMP()
FROM business_process_chain_definition source
JOIN business_process_chain_item item ON item.chain_definition_id=source.id
JOIN business_process_definition previous ON previous.id=item.process_definition_id
JOIN business_process_definition updated ON updated.process_code='pde-sales-delivery-learning' AND updated.version_number=7
JOIN business_process_chain_definition target ON target.chain_code=source.chain_code AND target.version_number=15
LEFT JOIN business_process_chain_item existing ON existing.chain_definition_id=target.id AND existing.sequence_number=item.sequence_number
WHERE source.chain_code='pde-value-creation-delivery' AND source.version_number=14 AND existing.id IS NULL;

UPDATE business_process_definition SET status='PUBLISHED' WHERE (process_code='opala-commercial-preparation-v1' AND version_number=1) OR (process_code='pde-sales-delivery-learning' AND version_number=7);
UPDATE business_process_chain_definition SET status='PUBLISHED' WHERE chain_code='pde-value-creation-delivery' AND version_number=15;
